window.CERT_DATA=window.CERT_DATA||{};window.CERT_DATA['bigdata-6']={"round":6,"cert":"bigdata","questions":[{"id":"6a6a005a1bbde79cd2c72ad8","number":1,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>세 개의 데이터 60, 70, 80에 최소-최대 정규화(Min-Max Normalization)를 적용했을 때, 변환된 값들의 합은 얼마인가?</p>","choices":[{"n":1,"html":"1"},{"n":2,"html":"1.5"},{"n":3,"html":"2"},{"n":4,"html":"2.5"}],"answer":[2]},{"id":"6a6a005a1bbde79cd2c72aca","number":2,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>빅데이터 분석 업무 수행을 위한 조직 구조에 관한 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"집중 구조는 분석 업무를 전담 조직에서 수행하므로 다른 현업 부서와 업무가 중복되지 않는다."},{"n":2,"html":"분산 구조는 분석 인력이 현업 부서에 배치되므로 부서별 역할 분담을 사전에 명확히 정해 두어야 한다."},{"n":3,"html":"빅데이터 분석 조직의 유형은 크게 집중 구조, 기능 구조, 분산 구조로 구분할 수 있다."},{"n":4,"html":"기능 구조는 업무를 각 해당 부서에서 수행하므로 전사 차원의 핵심 분석이 다소 어렵다."}],"answer":[1]},{"id":"6a6a005a1bbde79cd2c72acd","number":3,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>다음 중 데이터 거버넌스(Data Governance)를 구성하는 요소에 해당하지 않는 것은?</p>","choices":[{"n":1,"html":"조직(Organization)"},{"n":2,"html":"IT 인프라(IT Infra)"},{"n":3,"html":"원칙(Principle)"},{"n":4,"html":"프로세스(Process)"}],"answer":[2]},{"id":"6a6a005a1bbde79cd2c72acf","number":4,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>기업의 분석 준비도(Readiness)를 진단할 때 분석 업무 도입 방법론, 분석 기법의 라이브러리, 분석 효과성 평가, 정기적인 개선 여부 등을 점검 대상으로 삼는 진단 영역은 어느 것인가?</p>","choices":[{"n":1,"html":"분석 인력 및 조직 진단"},{"n":2,"html":"분석 활용 진단"},{"n":3,"html":"분석 기법 진단"},{"n":4,"html":"IT 인프라 진단"}],"answer":[3]},{"id":"6a6a005a1bbde79cd2c72ad1","number":5,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>데이터 분석 마스터 플랜을 수립하는 작업에 해당하는 것으로 옳은 것은?</p>","choices":[{"n":1,"html":"마지막 단계로 데이터 분석 보고서를 작성하고 빅데이터 분석결과에 시각화 기법을 적용한다."},{"n":2,"html":"분석 대상 과제의 현황을 파악·분석하고 개선 과제를 정의하여 도출한다."},{"n":3,"html":"데이터 분석 과제를 정의한 후 과제의 중요도와 난이도 등을 감안해 우선순위를 정하고, 단기 및 중장기로 나누어 분석 로드맵을 세운다."},{"n":4,"html":"분석 목표 및 프로젝트 계획에 근거하여 보유 중인 데이터 자산을 점검한다."}],"answer":[3]},{"id":"6a6a005a1bbde79cd2c72ac9","number":6,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>다음 중 빅데이터분석 산업이 갖는 단점에 해당하지 않는 것은?</p>","choices":[{"n":1,"html":"인간과 인간(Human to Human) 간의 연결이 언제든지 가능해졌다."},{"n":2,"html":"이성적 능력으로는 예측할 수 없는 수많은 미지의 예측들로 인해 빅데이터에 대한 의존이 심해질 수 있다."},{"n":3,"html":"개인정보가 유출되어 보안 문제가 생길 수 있다."},{"n":4,"html":"개인의 프라이버시가 침해될 우려가 있다."}],"answer":[1]},{"id":"6a6a005a1bbde79cd2c72ad0","number":7,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>인공지능 시스템을 구현하는 기법에 관한 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"딥러닝의 일부가 머신러닝이다."},{"n":2,"html":"머신러닝은 컴퓨터가 명시적으로 프로그램되지 않아도 스스로 학습할 수 있게 하는 연구 분야로, 지도, 비지도, 강화 등의 학습 방법을 활용한다."},{"n":3,"html":"인공신경망은 인간의 뉴런 구조를 소프트웨어적으로 본떠 만든 머신러닝 모델로서 인공지능 기술의 한 형태에 해당한다."},{"n":4,"html":"딥러닝은 인간의 뇌 신경망을 본뜬 인공신경망의 한 종류에 해당한다."}],"answer":[1]},{"id":"6a6a005a1bbde79cd2c72ad2","number":8,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>데이터 탐색 업무에 관한 설명 중 가장 적절하지 않은 것은 무엇인가?</p>","choices":[{"n":1,"html":"데이터의 탐색과 시각화를 통해 통찰력을 발견하고 조사 영역과 패턴을 식별한다."},{"n":2,"html":"변수 파악, 통계량 산출, 상관분석 등을 수행하며 시각화를 통해 Data Insights를 얻는다."},{"n":3,"html":"분석 대상이 되는 데이터를 살펴봄으로써 데이터의 특징을 파악한다."},{"n":4,"html":"데이터 분석 모형의 수행 결과를 해석하는 업무가 이에 해당한다."}],"answer":[4]},{"id":"6a6a005a1bbde79cd2c72adb","number":9,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>사양이 낮은 서버들로 구성된 제한적인 환경에서 빅데이터를 효율적으로 저장하고자 할 때, 대용량·데이터 집중형 애플리케이션을 지원하면서 사용자에게 고성능의 Fault-tolerant 환경을 제공하기 위해 고려할 수 있는 저장 시스템은 무엇인가?</p>","choices":[{"n":1,"html":"분산 파일 시스템"},{"n":2,"html":"병렬 파일 시스템"},{"n":3,"html":"데이터베이스 시스템"},{"n":4,"html":"레거시 시스템"}],"answer":[1]},{"id":"6a6a005a1bbde79cd2c72ad7","number":10,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>데이터 전처리 과정에서 이루어지는 데이터 정제(Data Cleansing) 업무에 해당하지 않는 것은 다음 중 무엇인가?</p>","choices":[{"n":1,"html":"분석 목적에 부합하고 데이터 분석가가 이해하기 용이하도록 데이터 유형을 변환한다."},{"n":2,"html":"데이터 결측치 문제에 대응하고자 표본을 재수집하여 결측값을 보완한다."},{"n":3,"html":"이상값 데이터를 결측값으로 대체하거나 해당 이상치를 제거(Trimming)한다."},{"n":4,"html":"노이즈(잡음) 데이터 문제에 대응하고자 평균에서 3×표준편차를 초과하는 값을 제거한다."}],"answer":[1]},{"id":"6a6a005a1bbde79cd2c72ad5","number":11,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>데이터의 유형은 정형, 반정형, 비정형으로 나눌 수 있다. 이러한 구분과 가장 관련이 깊은 빅데이터의 특성은 무엇인가?</p>","choices":[{"n":1,"html":"규모"},{"n":2,"html":"속도"},{"n":3,"html":"가치"},{"n":4,"html":"다양성"}],"answer":[4]},{"id":"6a6a005a1bbde79cd2c72adc","number":12,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>분산 파일 시스템(Distributed File System)에 관한 설명 중 옳은 것은 무엇인가?</p>","choices":[{"n":1,"html":"네트워크 기반으로 동작하므로 노드 간 데이터 전송 과정에서 데이터 손실(또는 누락)이 생길 수 있으며, 다수의 클라이언트가 동일한 데이터에 동시에 접근하면 지연이나 장애가 발생할 수 있다."},{"n":2,"html":"사용자가 필요로 하는 파일들이 분산 저장되어 있으므로 여러 사용자가 원격으로 데이터를 공유하는 것이 불가능하다."},{"n":3,"html":"서비스에 필요한 컴퓨팅 자원 전부를 하나의 중앙 서버에 두기 때문에, 해당 서버에 오류가 나면 서비스 전체가 실패하게 된다."},{"n":4,"html":"데이터를 서로 다른 물리적 위치에 중복 저장하기 때문에 디스크 장애가 발생하면 복구하기 어렵다."}],"answer":[1]},{"id":"6a6a005a1bbde79cd2c72acc","number":13,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>데이터 분석으로 개선사항을 이끌어내고자 할 때, 분석 대상의 현황을 파악하여 개선과제를 정의하는 단계로 옳은 것은 무엇인가?</p>","choices":[{"n":1,"html":"분석목표 수립"},{"n":2,"html":"보유 데이터 자산 확인"},{"n":3,"html":"프로젝트 계획"},{"n":4,"html":"도메인 이슈 도출"}],"answer":[4]},{"id":"6a6a005a1bbde79cd2c72ada","number":14,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>데이터 저장 시스템에 관한 다음 설명 중 옳지 않은 것은 무엇인가?</p>","choices":[{"n":1,"html":"데이터 레이크는 데이터마트와 달리 더 많은 데이터를 모으기 위해 등장한 개념으로, 다양한 종류의 데이터를 수집한다는 관점에서 고안되었다."},{"n":2,"html":"데이터마트는 데이터웨어하우스를 경량화한 형태로, 주로 본부별·부서별 혹은 업무 영역별로 구축되는 소규모 데이터웨어하우스이다."},{"n":3,"html":"데이터 댐은 여러 곳에서 생산된 데이터를 수집·분류·가공하여 누구나 인공지능과 네트워크를 결합해 손쉽게 활용할 수 있도록 공급하는 시스템 개념이다."},{"n":4,"html":"데이터웨어하우스는 데이터 소매점, 데이터마트는 데이터 도매점의 개념으로 사용된다."}],"answer":[4]},{"id":"6a6a005a1bbde79cd2c72ad4","number":15,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>다음 중 외부 데이터에 관한 설명으로 가장 적절한 것은?</p>","choices":[{"n":1,"html":"소셜, 센서, 공개 데이터 등 상대적으로 잠재적 가치가 높으며 선택의 폭이 넓은 데이터를 수집할 수 있다."},{"n":2,"html":"조직 내부의 데이터 저장소를 활용하므로, 데이터 수집에 드는 비용이 저렴하다."},{"n":3,"html":"해당 소스 데이터 담당자와의 의사소통이 원활하므로 수집 난도가 비교적 낮은 편이다."},{"n":4,"html":"대부분이 정형 데이터에 해당하여 일반적인 CRUD 처리 아키텍처와 동일한 구성이 가능하다."}],"answer":[1]},{"id":"6a6a005a1bbde79cd2c72ad3","number":16,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>데이터를 수집하고 통계분석을 수행할 때 고려해야 할 사항에 대한 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"데이터 분석을 활용한 추론통계에서는 모집단을 이용하여 표본집단을 추론한다."},{"n":2,"html":"데이터를 수집한 뒤 기술통계에서는 분석에 필요한 통계적 기법을 활용해 데이터를 정리하고 요약한다."},{"n":3,"html":"데이터의 유형을 감안하여 유형별로 효율적인 수집 기술을 결정한다."},{"n":4,"html":"수집 대상 데이터의 위치에 따라 내부 데이터와 외부 데이터로 나뉘며, 외부 데이터는 수집 시 기술적 제약이 많고 수집 비용도 많이 소요된다."}],"answer":[1]},{"id":"6a6a005a1bbde79cd2c72ad6","number":17,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>데이터 안에 섞여 있는 노이즈(Noise, 잡음) 때문에 거칠게 분포하는 데이터를 부드럽게 다듬어 노이즈를 없애는 데이터 변환 기법은?</p>","choices":[{"n":1,"html":"Aggregation(총계)"},{"n":2,"html":"Smoothing(스무딩)"},{"n":3,"html":"Min-Max Normalization(최소-최대 정규화)"},{"n":4,"html":"Normalization(정규화)"}],"answer":[2]},{"id":"6a6a005a1bbde79cd2c72acb","number":18,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>다음 중 데이터 사이언스(Data Science)에 관한 설명으로 옳은 것은?</p>","choices":[{"n":1,"html":"인문, 사회, 의학, 공학 등 다양한 분야 전반에 걸쳐 폭넓게 활용되고 있다."},{"n":2,"html":"의학, 공학 등의 분야에서는 활발히 사용되고 있으나 비즈니스 인사이트 추출에는 한계가 있어 널리 활용되지 못하고 있다."},{"n":3,"html":"데이터 사이언스는 데이터 마이닝, 머신러닝, 예측·분류분석 등 확률 및 통계 분야에만 국한되어 적용되는 영역이다."},{"n":4,"html":"데이터로부터 인사이트를 도출하기 위한 종합적인 접근 방법이기는 하나 데이터 가치와는 거리가 멀다."}],"answer":[1]},{"id":"6a6a005a1bbde79cd2c72ace","number":19,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>어느 기업의 데이터 분석 수준을 진단해 본 결과, 분석 준비도는 기준치보다 낮게 나타났으나 비즈니스, 조직, 역량, IT 영역의 성숙도는 높다고 평가되었다. 사분면 분석결과에 따르면 이 기업은 어떤 유형에 속하는가?</p>","choices":[{"n":1,"html":"준비형 수준"},{"n":2,"html":"정착형 수준"},{"n":3,"html":"확산형 수준"},{"n":4,"html":"도입형 수준"}],"answer":[2]},{"id":"6a6a005a1bbde79cd2c72ad9","number":20,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>비정형 데이터가 지닌 특성에 대한 설명으로 옳은 것은 무엇인가?</p>","choices":[{"n":1,"html":"일반적으로 NoSQL 데이터베이스에 저장된다."},{"n":2,"html":"일반적으로 전통적인 관계형 데이터베이스에 저장된다."},{"n":3,"html":"데이터 저장 시스템을 선정할 때 데이터 유형은 고려할 필요가 없다."},{"n":4,"html":"분산 파일 시스템에는 저장이 불가능하다."}],"answer":[1]},{"id":"6a6a005a1bbde79cd2c72ae9","number":21,"category":"빅데이터 탐색","type":"choice","subject":"<p>탐색적 데이터 분석(EDA, Exploratory Data Analysis)에 관한 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"자료 구조뿐 아니라 자료가 지닌 본연의 의미를 분석하는 과정으로, 데이터 분석 모형 적합 및 정교한 모형 개발에 도움이 된다."},{"n":2,"html":"주성분 분석(PCA, Principal Component Analysis) 과정은 여기에 포함되지 않는다."},{"n":3,"html":"EDA 분석을 효율적으로 진행하기 위해 여러 가지 데이터 시각화 방법을 활용한다."},{"n":4,"html":"분석 대상이 되는 상호 의미 있는 속성들 간에 상관관계를 갖는 속성의 조합을 탐색하는 과정이 포함된다."}],"answer":[2]},{"id":"6a6a005a1bbde79cd2c72ae3","number":22,"category":"빅데이터 탐색","type":"choice","subject":"<p>상자 모양과 T자형 선을 이용해 데이터를 표현함으로써 중앙값, 사분위 범위, 이상치 등을 파악할 수 있는 아래와 같은 차트를 무엇이라고 하는가?</p><div class=\"q-fig\"><svg class=\"q-fig__svg\" viewBox=\"0 0 760 385\" width=\"760\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"상자와 수염, 사분위수와 중앙값, 이상점·극단점 표시를 나타낸 가로형 개념도\"><defs><marker id=\"iqrArw\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\"><path d=\"M0 0L10 5L0 10z\" fill=\"currentColor\"/></marker></defs><line x1=\"150\" y1=\"175\" x2=\"150\" y2=\"225\" stroke=\"currentColor\" stroke-width=\"2.2\"/><line x1=\"150\" y1=\"200\" x2=\"260\" y2=\"200\" stroke=\"currentColor\" stroke-width=\"1.8\"/><rect x=\"260\" y=\"140\" width=\"280\" height=\"120\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"350\" y1=\"140\" x2=\"350\" y2=\"260\" stroke=\"currentColor\" stroke-width=\"2.6\"/><line x1=\"540\" y1=\"200\" x2=\"650\" y2=\"200\" stroke=\"currentColor\" stroke-width=\"1.8\"/><line x1=\"650\" y1=\"175\" x2=\"650\" y2=\"225\" stroke=\"currentColor\" stroke-width=\"2.2\"/><circle cx=\"700\" cy=\"200\" r=\"5\" fill=\"currentColor\"/><circle cx=\"740\" cy=\"200\" r=\"5\" fill=\"currentColor\"/><line x1=\"265\" y1=\"235\" x2=\"535\" y2=\"235\" stroke=\"currentColor\" stroke-width=\"1.4\" marker-start=\"url(#iqrArw)\" marker-end=\"url(#iqrArw)\"/><text x=\"445\" y=\"224\" font-size=\"12\" fill=\"currentColor\" text-anchor=\"middle\">사분위범위(IQR)</text><line x1=\"150\" y1=\"120\" x2=\"150\" y2=\"172\" stroke=\"currentColor\" stroke-width=\"1\" stroke-dasharray=\"4 3\"/><text x=\"150\" y=\"110\" font-size=\"13.5\" fill=\"currentColor\" text-anchor=\"middle\">최솟값(Minimum)</text><line x1=\"350\" y1=\"58\" x2=\"350\" y2=\"138\" stroke=\"currentColor\" stroke-width=\"1\" stroke-dasharray=\"4 3\"/><text x=\"350\" y=\"48\" font-size=\"13.5\" fill=\"currentColor\" text-anchor=\"middle\">Q2-제2사분위수, 중앙값(Median)</text><line x1=\"650\" y1=\"120\" x2=\"650\" y2=\"173\" stroke=\"currentColor\" stroke-width=\"1\" stroke-dasharray=\"4 3\"/><text x=\"650\" y=\"110\" font-size=\"13.5\" fill=\"currentColor\" text-anchor=\"middle\">최댓값(Maximum)</text><line x1=\"740\" y1=\"58\" x2=\"740\" y2=\"192\" stroke=\"currentColor\" stroke-width=\"1\" stroke-dasharray=\"4 3\"/><text x=\"755\" y=\"48\" font-size=\"13.5\" fill=\"currentColor\" text-anchor=\"end\">극단점(Extreme)</text><line x1=\"205\" y1=\"205\" x2=\"205\" y2=\"300\" stroke=\"currentColor\" stroke-width=\"1\" stroke-dasharray=\"4 3\"/><text x=\"205\" y=\"320\" font-size=\"13.5\" fill=\"currentColor\" text-anchor=\"middle\">수염(Whisker)</text><line x1=\"595\" y1=\"205\" x2=\"595\" y2=\"300\" stroke=\"currentColor\" stroke-width=\"1\" stroke-dasharray=\"4 3\"/><text x=\"595\" y=\"320\" font-size=\"13.5\" fill=\"currentColor\" text-anchor=\"middle\">수염(Whisker)</text><line x1=\"260\" y1=\"263\" x2=\"260\" y2=\"345\" stroke=\"currentColor\" stroke-width=\"1\" stroke-dasharray=\"4 3\"/><text x=\"260\" y=\"365\" font-size=\"13.5\" fill=\"currentColor\" text-anchor=\"middle\">Q1-제1사분위수(Lower quartile)</text><line x1=\"540\" y1=\"263\" x2=\"540\" y2=\"345\" stroke=\"currentColor\" stroke-width=\"1\" stroke-dasharray=\"4 3\"/><text x=\"540\" y=\"365\" font-size=\"13.5\" fill=\"currentColor\" text-anchor=\"middle\">Q3-제3사분위수(Upper quartile)</text><line x1=\"700\" y1=\"208\" x2=\"700\" y2=\"255\" stroke=\"currentColor\" stroke-width=\"1\" stroke-dasharray=\"4 3\"/><text x=\"690\" y=\"275\" font-size=\"13.5\" fill=\"currentColor\" text-anchor=\"middle\">이상점(Outlier)</text></svg></div>","choices":[{"n":1,"html":"히스토그램"},{"n":2,"html":"박스 플롯"},{"n":3,"html":"산점도"},{"n":4,"html":"점도표"}],"answer":[2]},{"id":"6a6a005a1bbde79cd2c72ade","number":23,"category":"빅데이터 탐색","type":"choice","subject":"<p>데이터의 추출·변환·적재(로드, 저장) 과정을 가리키는 용어로, 기존의 데이터를 저장 또는 집계해 분석한 뒤 비즈니스 의사결정에 활용하는 작업을 무엇이라 부르는가?</p>","choices":[{"n":1,"html":"Data Integration"},{"n":2,"html":"ETL"},{"n":3,"html":"Data Virtualization"},{"n":4,"html":"Data Loading"}],"answer":[2]},{"id":"6a6a005a1bbde79cd2c72aed","number":24,"category":"빅데이터 탐색","type":"choice","subject":"<p>다음 중 기술통계량에 관한 설명 가운데 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"중앙값(Median)은 데이터를 크기 순으로 배열하였을 때 정중앙에 위치하는 값이다."},{"n":2,"html":"첨도(Kurtosis)는 표준정규분포와 비교했을 때 분포의 양끝이 어느 정도 뾰족한 모양인지를 보여준다."},{"n":3,"html":"왜도(Skewness)는 평균을 기준으로 한 비대칭의 정도(왼쪽 혹은 오른쪽 꼬리 형태)를 나타내는 값이다."},{"n":4,"html":"범위(Range)는 최댓값과 최솟값의 차이로, 데이터가 분포해 있는 영역의 크기를 보여준다."}],"answer":[2]},{"id":"6a6a005a1bbde79cd2c72aea","number":25,"category":"빅데이터 탐색","type":"choice","subject":"<p>아래 그림처럼 독립변수(X)와 종속변수(Y)가 교차하는 지점을 도표 위에 점으로 나타내면 두 변수 간의 관계를 파악할 수 있다. 이러한 도표를 무엇이라고 하는가?</p><div class=\"q-fig\"><svg class=\"q-fig__svg\" viewBox=\"0 0 560 385\" width=\"560\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"X축과 Y축 평면 위에 두 변수의 값이 만나는 위치마다 점을 찍어 흩뿌려 놓은 그림\"><defs><marker id=\"ah2\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\"><path d=\"M0 0L10 5L0 10z\" fill=\"currentColor\"/></marker></defs><line x1=\"70\" y1=\"340\" x2=\"70\" y2=\"32\" stroke=\"currentColor\" stroke-width=\"1.6\" marker-end=\"url(#ah2)\"/><line x1=\"70\" y1=\"340\" x2=\"548\" y2=\"340\" stroke=\"currentColor\" stroke-width=\"1.6\" marker-end=\"url(#ah2)\"/><text x=\"58\" y=\"36\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"end\">Y</text><text x=\"546\" y=\"362\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"middle\">X</text><line x1=\"64\" y1=\"280\" x2=\"70\" y2=\"280\" stroke=\"currentColor\" stroke-width=\"1.6\"/><text x=\"58\" y=\"284\" font-size=\"13\" fill=\"currentColor\" text-anchor=\"end\">20</text><line x1=\"64\" y1=\"220\" x2=\"70\" y2=\"220\" stroke=\"currentColor\" stroke-width=\"1.6\"/><text x=\"58\" y=\"224\" font-size=\"13\" fill=\"currentColor\" text-anchor=\"end\">40</text><line x1=\"64\" y1=\"160\" x2=\"70\" y2=\"160\" stroke=\"currentColor\" stroke-width=\"1.6\"/><text x=\"58\" y=\"164\" font-size=\"13\" fill=\"currentColor\" text-anchor=\"end\">60</text><line x1=\"64\" y1=\"100\" x2=\"70\" y2=\"100\" stroke=\"currentColor\" stroke-width=\"1.6\"/><text x=\"58\" y=\"104\" font-size=\"13\" fill=\"currentColor\" text-anchor=\"end\">80</text><line x1=\"155\" y1=\"340\" x2=\"155\" y2=\"346\" stroke=\"currentColor\" stroke-width=\"1.6\"/><text x=\"155\" y=\"362\" font-size=\"13\" fill=\"currentColor\" text-anchor=\"middle\">10</text><line x1=\"240\" y1=\"340\" x2=\"240\" y2=\"346\" stroke=\"currentColor\" stroke-width=\"1.6\"/><text x=\"240\" y=\"362\" font-size=\"13\" fill=\"currentColor\" text-anchor=\"middle\">20</text><line x1=\"325\" y1=\"340\" x2=\"325\" y2=\"346\" stroke=\"currentColor\" stroke-width=\"1.6\"/><text x=\"325\" y=\"362\" font-size=\"13\" fill=\"currentColor\" text-anchor=\"middle\">30</text><line x1=\"410\" y1=\"340\" x2=\"410\" y2=\"346\" stroke=\"currentColor\" stroke-width=\"1.6\"/><text x=\"410\" y=\"362\" font-size=\"13\" fill=\"currentColor\" text-anchor=\"middle\">40</text><line x1=\"495\" y1=\"340\" x2=\"495\" y2=\"346\" stroke=\"currentColor\" stroke-width=\"1.6\"/><text x=\"495\" y=\"362\" font-size=\"13\" fill=\"currentColor\" text-anchor=\"middle\">50</text><circle cx=\"92\" cy=\"91\" r=\"3\" fill=\"currentColor\"/><circle cx=\"103\" cy=\"58\" r=\"3\" fill=\"currentColor\"/><circle cx=\"115\" cy=\"111\" r=\"3\" fill=\"currentColor\"/><circle cx=\"122\" cy=\"70\" r=\"3\" fill=\"currentColor\"/><circle cx=\"128\" cy=\"82\" r=\"3\" fill=\"currentColor\"/><circle cx=\"140\" cy=\"118\" r=\"3\" fill=\"currentColor\"/><circle cx=\"152\" cy=\"76\" r=\"3\" fill=\"currentColor\"/><circle cx=\"165\" cy=\"112\" r=\"3\" fill=\"currentColor\"/><circle cx=\"178\" cy=\"142\" r=\"3\" fill=\"currentColor\"/><circle cx=\"190\" cy=\"100\" r=\"3\" fill=\"currentColor\"/><circle cx=\"200\" cy=\"154\" r=\"3\" fill=\"currentColor\"/><circle cx=\"203\" cy=\"133\" r=\"3\" fill=\"currentColor\"/><circle cx=\"216\" cy=\"99\" r=\"3\" fill=\"currentColor\"/><circle cx=\"229\" cy=\"155\" r=\"3\" fill=\"currentColor\"/><circle cx=\"241\" cy=\"130\" r=\"3\" fill=\"currentColor\"/><circle cx=\"254\" cy=\"174\" r=\"3\" fill=\"currentColor\"/><circle cx=\"267\" cy=\"130\" r=\"3\" fill=\"currentColor\"/><circle cx=\"280\" cy=\"161\" r=\"3\" fill=\"currentColor\"/><circle cx=\"292\" cy=\"189\" r=\"3\" fill=\"currentColor\"/><circle cx=\"300\" cy=\"133\" r=\"3\" fill=\"currentColor\"/><circle cx=\"305\" cy=\"155\" r=\"3\" fill=\"currentColor\"/><circle cx=\"318\" cy=\"191\" r=\"3\" fill=\"currentColor\"/><circle cx=\"331\" cy=\"154\" r=\"3\" fill=\"currentColor\"/><circle cx=\"343\" cy=\"194\" r=\"3\" fill=\"currentColor\"/><circle cx=\"350\" cy=\"169\" r=\"3\" fill=\"currentColor\"/><circle cx=\"356\" cy=\"223\" r=\"3\" fill=\"currentColor\"/><circle cx=\"369\" cy=\"180\" r=\"3\" fill=\"currentColor\"/><circle cx=\"381\" cy=\"207\" r=\"3\" fill=\"currentColor\"/><circle cx=\"394\" cy=\"177\" r=\"3\" fill=\"currentColor\"/><circle cx=\"400\" cy=\"222\" r=\"3\" fill=\"currentColor\"/><circle cx=\"407\" cy=\"237\" r=\"3\" fill=\"currentColor\"/><circle cx=\"420\" cy=\"215\" r=\"3\" fill=\"currentColor\"/><circle cx=\"432\" cy=\"239\" r=\"3\" fill=\"currentColor\"/><circle cx=\"445\" cy=\"208\" r=\"3\" fill=\"currentColor\"/><circle cx=\"458\" cy=\"265\" r=\"3\" fill=\"currentColor\"/><circle cx=\"470\" cy=\"231\" r=\"3\" fill=\"currentColor\"/><circle cx=\"478\" cy=\"281\" r=\"3\" fill=\"currentColor\"/><circle cx=\"483\" cy=\"263\" r=\"3\" fill=\"currentColor\"/><circle cx=\"496\" cy=\"227\" r=\"3\" fill=\"currentColor\"/><circle cx=\"508\" cy=\"266\" r=\"3\" fill=\"currentColor\"/><circle cx=\"521\" cy=\"290\" r=\"3\" fill=\"currentColor\"/><circle cx=\"530\" cy=\"262\" r=\"3\" fill=\"currentColor\"/></svg></div>","choices":[{"n":1,"html":"히스토그램"},{"n":2,"html":"산점도"},{"n":3,"html":"점도표"},{"n":4,"html":"박스 플롯"}],"answer":[2]},{"id":"6a6a005a1bbde79cd2c72af0","number":26,"category":"빅데이터 탐색","type":"choice","subject":"<p>K은행에서는 한 시간 동안 창구 업무를 위해 방문하는 고객 수의 평균(m)과 아래에 제시된 분포를 활용하여, 업무를 차질 없이 처리하는 데 필요한 적정 직원 수를 산정하려고 한다. 이때 이용하는 분포는 다음 중 무엇인가? (단, e=2.718282는 자연상수이다.)</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f</mi><mo stretchy=\"false\">(</mo><mi>x</mi><mo stretchy=\"false\">)</mo><mo>=</mo><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mfrac><mrow><msup><mi>e</mi><mrow><mo>−</mo><mi>m</mi></mrow></msup><mtext> </mtext><msup><mi>m</mi><mi>x</mi></msup></mrow><mrow><mi>x</mi><mo stretchy=\"false\">!</mo></mrow></mfrac></mstyle><mo separator=\"true\">,</mo><mspace width=\"1em\"/><mi>x</mi><mo>=</mo><mn>0</mn><mo separator=\"true\">,</mo><mtext> </mtext><mn>1</mn><mo separator=\"true\">,</mo><mtext> </mtext><mn>2</mn><mo separator=\"true\">,</mo><mtext> </mtext><mo>⋯</mo></mrow></semantics></math></span></p></div>","choices":[{"n":1,"html":"포아송분포"},{"n":2,"html":"기하분포"},{"n":3,"html":"다항분포"},{"n":4,"html":"이항분포"}],"answer":[1]},{"id":"6a6a005a1bbde79cd2c72ae5","number":27,"category":"빅데이터 탐색","type":"choice","subject":"<p>주성분 분석(PCA, Principal Component Analysis)에 관한 설명 중 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"기존 변수들을 조합해 서로 연관성이 없는 새로운 변수인 주성분들을 생성한다."},{"n":2,"html":"차원축소 기법의 하나로서, 원 데이터의 분포를 최대한 유지하면서 고차원 공간의 데이터를 저차원 공간으로 변환한다."},{"n":3,"html":"데이터를 하나의 축으로 사상시켰을 때 분산이 가장 크게 나타나는 축이 첫 번째 주성분, 그다음으로 분산이 큰 축이 두 번째 주성분이 되도록 새로운 좌표계로 데이터를 선형 변환한다."},{"n":4,"html":"음수가 포함되지 않은, 즉 전체 원소가 양수인 행렬 V를 음수를 포함하지 않는 두 행렬 W와 H의 곱으로 분해한다."}],"answer":[4]},{"id":"6a6a005a1bbde79cd2c72aee","number":28,"category":"빅데이터 탐색","type":"choice","subject":"<p>독립변수 X에 대해 어떤 사건이 발생할 확률을 p=P(Y=1|X)라고 하자. Odds Ratio(오즈비, O₁=p/(1-p))와 파라미터 (a, b)의 관계가 아래와 같이 주어질 때, X 값이 1만큼 커지면 O₁ 대비 Odds Ratio(O₂)는 몇 배로 증가(O₂/O₁)하는가?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ln</mi><mo>⁡</mo><mo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">(</mo><mi>p</mi><mi mathvariant=\"normal\">/</mi><mo stretchy=\"false\">(</mo><mn>1</mn><mo>−</mo><mi>p</mi><mo stretchy=\"false\">)</mo><mo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">)</mo><mo>=</mo><mi>a</mi><mo>+</mo><mi>b</mi><mi>X</mi></mrow></semantics></math></span></p></div>","choices":[{"n":1,"html":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>e</mi><mi>b</mi></msup></mrow></semantics></math></span> 증가"},{"n":2,"html":"1 증가"},{"n":3,"html":"증가하지 않는다."},{"n":4,"html":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>e</mi><mi>a</mi></msup></mrow></semantics></math></span> 증가"}],"answer":[1]},{"id":"6a6a005a1bbde79cd2c72ae1","number":29,"category":"빅데이터 탐색","type":"choice","subject":"<p>데이터 이상값(Outlier)이 발생하는 원인에 해당하지 않는 것은 다음 중 무엇인가?</p>","choices":[{"n":1,"html":"측정 오류(Measurement Error)"},{"n":2,"html":"처리 오류(Processing Error)"},{"n":3,"html":"보고 오류(Reporting Error)"},{"n":4,"html":"표본 오류(Sampling Error)"}],"answer":[3]},{"id":"6a6a005a1bbde79cd2c72add","number":30,"category":"빅데이터 탐색","type":"choice","subject":"<p>다음 보기 가운데 데이터 전처리(Data Pre-processing) 과정에 포함되지 않는 작업은 무엇인가?</p>","choices":[{"n":1,"html":"데이터 준비(Collection)"},{"n":2,"html":"데이터 정제(Cleansing)"},{"n":3,"html":"데이터 유형 변환(Type Transformation)"},{"n":4,"html":"데이터 필터링(Filtering)"}],"answer":[1]},{"id":"6a6a005a1bbde79cd2c72ae2","number":31,"category":"빅데이터 탐색","type":"choice","subject":"<p>이상값(Outlier)의 처리에 대한 설명 중 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"이상값은 분석 목적이나 유형에 따라 제거하거나 대체할 수 있으며, 대체 시에는 평균, 최빈값, 중앙값, 예측값 등이 활용된다."},{"n":2,"html":"이상값은 관측된 데이터 범위에서 크게 벗어난 매우 작거나 큰 값을 말하며, 의사결정에 큰 영향을 줄 수 있으므로 데이터 전처리 단계에서 적절히 처리하는 것이 필수적이다."},{"n":3,"html":"이상값을 평균값으로 대체해 사용하면 데이터 변환 작업 과정에서 데이터의 신뢰도 문제가 발생하지 않는다."},{"n":4,"html":"박스 플롯을 활용해 이상값을 탐지할 때는 사분위수 범위값을 이용할 수 있다."}],"answer":[3]},{"id":"6a6a005a1bbde79cd2c72adf","number":32,"category":"빅데이터 탐색","type":"choice","subject":"<p>아래 설명에 해당하는 MapReduce 작업의 디자인 패턴(Design Pattern)으로 옳은 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>서로 간의 특별한 관계를 찾아내기 위해 다른 데이터세트를 함께 분석한다.</li><li>하둡 맵리듀스를 활용할 때 서로 다른 유형의 데이터세트를 함께 분석하는 용도로 대표적으로 쓰인다.</li><li>연산이 실제로 수행되는 위치를 기준으로 Map 단에서의 연산과 Reduce 단에서의 연산으로 구분된다.</li><li>이항연산자인 경우 입력이 두 개 필요하다.</li></ul></div>","choices":[{"n":1,"html":"필터링 패턴"},{"n":2,"html":"조인 패턴"},{"n":3,"html":"메타 패턴"},{"n":4,"html":"요약 패턴"}],"answer":[2]},{"id":"6a6a005a1bbde79cd2c72aef","number":33,"category":"빅데이터 탐색","type":"choice","subject":"<p>K대학병원의 조사에 따르면, 흡연자 200명 가운데 폐암 환자가 20명이었고, 비흡연자 220명 가운데 폐암 환자가 4명이었다. 흡연 여부에 따른 폐암의 오즈비(Odds Ratio)는 얼마인가?</p>","choices":[{"n":1,"html":"1"},{"n":2,"html":"4"},{"n":3,"html":"5"},{"n":4,"html":"6"}],"answer":[4]},{"id":"6a6a005a1bbde79cd2c72ae6","number":34,"category":"빅데이터 탐색","type":"choice","subject":"<p>다음 중 파생변수(Derived Variable)를 활용한 사례로 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"키와 몸무게를 이용해 BMI(체질량 지수) = 몸무게/(키×키) 변수 생성"},{"n":2,"html":"나이의 결측값을 평균값으로 채워 생성"},{"n":3,"html":"원점수(0~100)에 표준편차를 반영하여 수능 표준점수 생성"},{"n":4,"html":"주민번호를 이용해 나이 생성"}],"answer":[2]},{"id":"6a6a005a1bbde79cd2c72ae7","number":35,"category":"빅데이터 탐색","type":"choice","subject":"<p>다음 중 변수 변환 기법인 원-핫 인코딩(One-hot Encoding)에 관한 설명으로 옳지 않은 것은?</p>","choices":[{"n":1,"html":"표현하려는 단어의 인덱스에는 1을, 나머지 인덱스에는 0을 부여하며, 단어 집합의 크기를 벡터의 차원으로 삼는 방식에 적용된다."},{"n":2,"html":"수많은 0과 단 한 개의 1의 값으로 데이터를 구별하는 인코딩 방법이다."},{"n":3,"html":"범주형 변수를 숫자형 변수로 바꾸는 과정에서 공간을 효율적으로 활용하게 된다."},{"n":4,"html":"범주형의 종류 개수 크기의 벡터를 0으로 초기화한 뒤, 특정 범주를 표현하기 위해 해당 위치의 값을 1로 지정한다."}],"answer":[3]},{"id":"6a6a005a1bbde79cd2c72ae4","number":36,"category":"빅데이터 탐색","type":"choice","subject":"<p>다음 보기 가운데 변수의 특성이 나머지와 다른 것은 무엇인가?</p>","choices":[{"n":1,"html":"혈액형"},{"n":2,"html":"실내의 온도"},{"n":3,"html":"사람의 키"},{"n":4,"html":"책의 두께"}],"answer":[1]},{"id":"6a6a005a1bbde79cd2c72aec","number":37,"category":"빅데이터 탐색","type":"choice","subject":"<p>측정 단위가 상이한 자료들을 서로 비교하고자 할 때 주로 활용되며, 표준편차를 표본평균(또는 모평균)으로 나누어 구하는 값은 무엇인가?</p>","choices":[{"n":1,"html":"왜도(Skewness)"},{"n":2,"html":"첨도(Kurtosis)"},{"n":3,"html":"범위(Range)"},{"n":4,"html":"변동계수(Coefficient of Variation)"}],"answer":[4]},{"id":"6a6a005a1bbde79cd2c72ae0","number":38,"category":"빅데이터 탐색","type":"choice","subject":"<p>다음에서 설명하는 결측값 처리 기법으로 옳은 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p>관측되지 않았거나 칸이 비어 있는 결측치를 다루기 위해 평균 대치, 단순 확률 대치 등을 한 번만 수행하는 대신, m번의 대치를 거쳐 m개의 가상적인 완전한 자료를 생성하여 분석하며, 대치, 분석, 결합의 단계로 진행한다.</p></div>","choices":[{"n":1,"html":"단순 대치법(Single Imputation)"},{"n":2,"html":"다중 대치법(Multiple Imputation)"},{"n":3,"html":"평균 대치법(Mean Imputation)"},{"n":4,"html":"단순 확률 대치법(Single Stochastic Imputation)"}],"answer":[2]},{"id":"6a6a005a1bbde79cd2c72aeb","number":39,"category":"빅데이터 탐색","type":"choice","subject":"<p>모집단으로부터 추출된 아래 표본 데이터의 평균과 표본분산을 계산하면 얼마인가?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p>2, 4, 6, 8, 10</p></div>","choices":[{"n":1,"html":"평균 = 6, 분산 = 8"},{"n":2,"html":"평균 = 6, 분산 = 10"},{"n":3,"html":"평균 = 7, 분산 = 8"},{"n":4,"html":"평균 = 7, 분산 = 10"}],"answer":[2]},{"id":"6a6a005a1bbde79cd2c72ae8","number":40,"category":"빅데이터 탐색","type":"choice","subject":"<p>클래스 불균형(Class Imbalance, 데이터 불균형)에 관한 다음 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"Weight Balancing(클래스 가중치 조정) 기법으로는 불균형 문제를 해결하는 것이 불가능하다."},{"n":2,"html":"Oversampling(오버샘플링)은 원본 데이터의 성질을 동일하게 유지하면서 양이 적은 데이터를 양이 많은 데이터 수준으로 샘플링하는 방법이다."},{"n":3,"html":"Undersampling(언더샘플링)은 대표성이 잘 유지되도록 양이 많은 데이터를 양이 적은 데이터 수준으로 샘플링하는 방법이다."},{"n":4,"html":"클래스 불균형은 주로 클래스의 개수 자체보다는 클래스별 샘플 수와 관련된 문제를 의미한다."}],"answer":[1]},{"id":"6a6a005a1bbde79cd2c72af8","number":41,"category":"빅데이터 모델링","type":"choice","subject":"<p>회귀분석 모형을 적용하기 전에는 독립변수들 간의 상관관계(변수들 사이의 다중공선성)를 우선적으로 점검할 필요가 있다. 다중공선성을 측정하는 데 활용되는 지표로 알맞은 것은?</p>","choices":[{"n":1,"html":"Coefficient of Determination(결정계수)"},{"n":2,"html":"Studentized Residual(스튜던트화 잔차)"},{"n":3,"html":"Variance Inflation Factor(분산팽창지수)"},{"n":4,"html":"Mallow&#x27;s Cp(멜로우즈 Cp)"}],"answer":[3]},{"id":"6a6a005a1bbde79cd2c72af3","number":42,"category":"빅데이터 모델링","type":"choice","subject":"<p>회귀분석 모형의 성능 평가 지표 중 하나인 결정계수(Coefficient of Determination, R²)에 관한 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"결정계수는 0에서 1 사이의 값을 가지는데, 0에 가까우면 설명변수 X와 반응변수 Y 사이에 선형 상관관계의 정도가 없다고 보고, 1에 가까우면 선형 관계의 정도가 크다고 평가한다."},{"n":2,"html":"결정계수가 0에 가까우면 회귀식의 정확도가 매우 낮다고 보고, 1에 가까우면 정확도가 매우 높다고 평가한다."},{"n":3,"html":"분석 대상인 독립변수의 수가 많아질수록 결정계수는 0에 가까워지며, 적어질수록 1에 가까워진다."},{"n":4,"html":"결정계수는 회귀모형에서 설명변수 X에 의해 설명되는 반응변수 Y의 변동 비율로 계산된다."}],"answer":[3]},{"id":"6a6a005a1bbde79cd2c72aff","number":43,"category":"빅데이터 모델링","type":"choice","subject":"<p>의사결정나무 분석 알고리즘 가운데, 다항분포에서 우도비 검정통계량을 활용한 엔트로피 지수(Entropy Index)를 계산해 부모마디로부터 자식마디로 분기하는 기법은 어느 것인가?</p>","choices":[{"n":1,"html":"Alpha-Beta 가지치기(알파-베타컷)"},{"n":2,"html":"CHAID"},{"n":3,"html":"CART"},{"n":4,"html":"C4.5"}],"answer":[4]},{"id":"6a6a005a1bbde79cd2c72af4","number":44,"category":"빅데이터 모델링","type":"choice","subject":"<p>설명변수(독립변수)를 2개 이상 포함하는 다중회귀분석 모형을 만들 때 요구되는 가정으로 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"회귀모형의 잔차는 등분산성을 충족한다."},{"n":2,"html":"회귀모형의 잔차는 종속변수와 선형관계를 가진다."},{"n":3,"html":"개별 독립변수는 종속변수와 선형관계를 가진다."},{"n":4,"html":"회귀모형의 잔차는 평균이 0인 정규분포를 따른다."}],"answer":[2]},{"id":"6a6a005a1bbde79cd2c72b01","number":45,"category":"빅데이터 모델링","type":"choice","subject":"<p>시계열 데이터에서 시차를 둔 값들 간의 선형관계를 측정하면, 과거 시점의 자료를 활용하여 이후 시점의 값을 예측하는 것이 가능하다. 이와 같은 시계열 자료의 특성을 가리키는 용어는 무엇인가?</p>","choices":[{"n":1,"html":"주기성(Cycle)"},{"n":2,"html":"백색 잡음(White Noise)"},{"n":3,"html":"자기상관(Autocorrelation)"},{"n":4,"html":"계절성(Seasonality)"}],"answer":[3]},{"id":"6a6a005b1bbde79cd2c72b04","number":46,"category":"빅데이터 모델링","type":"choice","subject":"<p>랜덤포레스트(Random Forest)에 관한 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"랜덤포레스트는 결측치 처리가 용이하고 대용량 데이터 처리에 효과적이며 모델의 정확도를 높일 수 있지만, 학습 시 메모리 소모가 크다."},{"n":2,"html":"랜덤포레스트는 분류, 회귀분석 등에 활용되는 앙상블 학습 방법의 하나로, 훈련 과정에서 만들어진 다수의 결정 트리로부터 분류 결과나 평균 예측치를 출력한다."},{"n":3,"html":"원 자료에서 부트스트랩 샘플을 추출한 뒤, 각 부트스트랩 샘플마다 트리를 형성할 때 사용 가능한 모든 데이터를 학습한다."},{"n":4,"html":"랜덤포레스트는 의사결정나무 기법이 가진 오버피팅 한계를 극복하기 위한 전략의 하나로 제안되었으며, 훈련으로 구성한 여러 나무들의 결과를 최종적으로 취합해 결론을 도출한다."}],"answer":[3]},{"id":"6a6a005b1bbde79cd2c72b03","number":47,"category":"빅데이터 모델링","type":"choice","subject":"<p>앙상블 분석(Ensemble Analysis)의 배깅(Bagging)과 부스팅(Boosting) 학습 방법에 관한 다음 설명 중 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"배깅은 Bootstrap Aggregation의 줄임말로, 모형마다 임의의 데이터세트를 만들며 이때 만들어지는 데이터세트는 기존 데이터세트로부터 중복을 허용하여 추출한다."},{"n":2,"html":"부스팅 방식은 여러 모형을 서로 독립적으로 병렬 처리하며, 각 모형은 서로 영향을 주고받지 않는다."},{"n":3,"html":"배깅 기반 앙상블 모형에서는 전체 모형 결과의 평균을 구하거나(예측) 과반수 투표를 수행(분류)한다."},{"n":4,"html":"부스팅 방식은 이전 모형의 오차를 보완하는 방식으로, 데이터를 무작위로 선택하되 이전 학습에서 오차가 컸던 데이터에 가중치를 주어 데이터세트를 구성한다."}],"answer":[2]},{"id":"6a6a005a1bbde79cd2c72af9","number":48,"category":"빅데이터 모델링","type":"choice","subject":"<p>인과 분석(Causal Analysis)에 관한 설명으로 가장 적절한 것은?</p>","choices":[{"n":1,"html":"독립변수와 종속변수 간의 상관관계를 분석하는 것이다."},{"n":2,"html":"독립변수와 종속변수 간의 결정계수를 분석하는 것이다."},{"n":3,"html":"독립변수와 종속변수 간의 인과관계를 분석하는 것이다."},{"n":4,"html":"독립변수와 종속변수 간의 선형관계를 분석하는 것이다."}],"answer":[3]},{"id":"6a6a005a1bbde79cd2c72af7","number":49,"category":"빅데이터 모델링","type":"choice","subject":"<p>다음 중 회귀분석 모형을 구축하는 순서로 올바른 것은?</p>","choices":[{"n":1,"html":"분석 대상이 되는 독립변수와 종속변수 설정 → 회귀계수 추정 및 독립변수별 유의성 검정 → 기본 가정(선형성, 정규성, 등분산성, 독립성 등) 검증 → 회귀분석 모형의 유의성 검정 및 최종 모형 선정"},{"n":2,"html":"기본 가정(선형성, 정규성, 등분산성, 독립성 등) 검증 → 분석 대상이 되는 독립변수와 종속변수 설정 → 회귀계수 추정 및 독립변수별 유의성 검정 → 회귀분석 모형의 유의성 검정 및 최종 모형 선정"},{"n":3,"html":"기본 가정(선형성, 정규성, 등분산성, 독립성 등) 검증 → 회귀계수 추정 및 독립변수별 유의성 검정 → 분석 대상이 되는 독립변수와 종속변수 설정 → 회귀분석 모형의 유의성 검정 및 최종 모형 선정"},{"n":4,"html":"분석 대상이 되는 독립변수와 종속변수 설정 → 기본 가정(선형성, 정규성, 등분산성, 독립성 등) 검증 → 회귀계수 추정 및 독립변수별 유의성 검정 → 회귀분석 모형의 유의성 검정 및 최종 모형 선정"}],"answer":[4]},{"id":"6a6a005a1bbde79cd2c72af1","number":50,"category":"빅데이터 모델링","type":"choice","subject":"<p>독립변수가 연속형이며 종속변수가 범주형일 때 활용할 수 있는 데이터 분석 모형으로 가장 적절하지 않은 것은 다음 중 무엇인가?</p>","choices":[{"n":1,"html":"서포트벡터머신"},{"n":2,"html":"군집분석"},{"n":3,"html":"로지스틱 회귀분석"},{"n":4,"html":"다중선형 회귀분석"}],"answer":[4]},{"id":"6a6a005a1bbde79cd2c72af5","number":51,"category":"빅데이터 모델링","type":"choice","subject":"<p>어느 조사 자료가 1,000명의 대상자에 대해 변수 10,000개를 측정한 데이터세트(대상자의 수보다 변수의 수가 많은 경우)로 주어졌다. 이 데이터로 분석 모형을 구축하는 방법에 관한 설명 중 가장 옳지 않은 것은?</p>","choices":[{"n":1,"html":"고려하는 변수의 개수가 분석 대상자 수보다 많으면 회귀분석 모형에서 회귀계수 추정에 실패할 가능성이 높아진다."},{"n":2,"html":"독립변수가 많을 때는 차원축소 기법으로 유효 변수를 추정한 뒤, 홀드아웃이나 K-fold 교차 검증 방법을 통해 (학습, 검증) 데이터세트를 구성한다."},{"n":3,"html":"모형의 성능 검증을 위해서는 일반적으로 1,000명의 데이터세트로 동일한 과정을 100번 반복 수행한다."},{"n":4,"html":"차원의 저주(The Curse of Dimensionality)란 데이터 학습 과정에서 차원이 증가함에 따라 학습 데이터 수가 차원의 수보다 적어져 성능이 떨어지는 현상을 말한다."}],"answer":[3]},{"id":"6a6a005a1bbde79cd2c72af6","number":52,"category":"빅데이터 모델링","type":"choice","subject":"<p>데이터를 수집한 뒤 아래와 같은 문제를 해소하고자 실시하는 전처리 작업으로 옳은 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>데이터세트에 포함된 특성이 늘어나면, 특성 하나하나가 차원이 되어 차원이 증가한다.</li><li>대용량 데이터를 분석 대상으로 삼을 경우 소요 시간이 지나치게 길어져 현실적이지 않다.</li><li>데이터의 차원이 늘어날수록 데이터 공간의 부피는 기하급수적으로 커진다.</li><li>차원이 늘어나는 과정에서 학습 데이터의 수가 차원의 수보다 부족해져 성능이 떨어진다.</li><li>차원이 커질수록 각 차원 안에 존재하는 학습 데이터의 수는 줄어든다.</li></ul></div>","choices":[{"n":1,"html":"데이터 밸런싱(Data Balancing)"},{"n":2,"html":"데이터 변환(Data Transformation)"},{"n":3,"html":"데이터 축소(Data Reduction)"},{"n":4,"html":"데이터 정제(Data Cleansing)"}],"answer":[3]},{"id":"6a6a005a1bbde79cd2c72afc","number":53,"category":"빅데이터 모델링","type":"choice","subject":"<p>하나의 종속변수와 여러 개의 독립변수 간 선형관계를 분석하는 모형(다중선형회귀)의 성능 평가에 사용하는 지표로 알맞은 것은?</p>","choices":[{"n":1,"html":"데이터 전체의 흩어진 정도를 나타내는 값들 가운데 잔차 제곱합이 차지하는 비율을 사용한다."},{"n":2,"html":"단순선형회귀분석을 통해 얻은 결정계수를 사용한다."},{"n":3,"html":"분산팽창지수를 사용한다."},{"n":4,"html":"결정계수와 표본의 수, 독립변수의 수를 활용해 산출한 수정된 결정계수를 사용한다."}],"answer":[4]},{"id":"6a6a005a1bbde79cd2c72afa","number":54,"category":"빅데이터 모델링","type":"choice","subject":"<p>회귀분석에 관한 다음 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"레버리지 통계량 값이 높은 관측치는 대응하는 독립변수의 값이 보통 수준과 다른 경우이며, 이는 회귀분석 결과에 큰 영향을 미치지 않는다."},{"n":2,"html":"두 개 이상의 설명변수(독립변수)들이 서로 밀접하게 상관되어 있는 경우, 다중공선성(Multicollinearity)을 검출하여 해당 변수를 제외하거나 차원축소(변수 결합) 기법을 적용한다."},{"n":3,"html":"주어진 잔차(관측치-예측치)를 설명변수(독립변수)에 대해 그래프로 나타냈을 때 일정한 패턴이 나타난다면, 선형 회귀분석 모형에 문제가 있는 것이므로 다항 회귀나 비선형적 모형 등 다른 모형을 적용한다."},{"n":4,"html":"회귀분석 모형이 예측한 값과 관측치가 크게 차이 나는 경우, 아웃라이어(Outlier, 이상치) 값을 식별하기 위해 Tukey Fence나 Z-score 방법을 활용한다."}],"answer":[1]},{"id":"6a6a005a1bbde79cd2c72b00","number":55,"category":"빅데이터 모델링","type":"choice","subject":"<p>시계열 분석에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>(가) 시계열 자료는 크게 정상성(Stationarity) 자료와 비정상성(Non-Stationarity) 자료로 나뉘며, 비정상성 자료에 대한 시계열 분석이 더 어렵다.</li><li>(나) 횡단면 자료와 마찬가지로 종단면 자료 즉 시계열 자료도 관측값들 간의 독립성이 중요하다.</li><li>(다) 지수평활법은 과거의 값에는 큰 가중치를 부여하고 최근 자료에는 더 작은 가중치를 적용한다.</li><li>(라) 이동평균법은 과거에서 현재까지의 시계열 자료를 대상으로 일정 기간 단위의 이동평균을 산출하고 그 추세를 파악하여 다음 기간을 예측하는 방법이다.</li></ul></div>","choices":[{"n":1,"html":"(다), (라)"},{"n":2,"html":"(가), (나)"},{"n":3,"html":"(나), (다)"},{"n":4,"html":"(나), (라)"}],"answer":[3]},{"id":"6a6a005a1bbde79cd2c72b02","number":56,"category":"빅데이터 모델링","type":"choice","subject":"<p>Reset 게이트와 Update 게이트를 활용하여 순환신경망(Recurrent Neural Network)의 학습시간을 단축하고 성능을 향상시키는 딥러닝 기법으로 옳은 것은?</p>","choices":[{"n":1,"html":"Deep Belief Network(DBF)"},{"n":2,"html":"Long Short-Term Memory(LSTM)"},{"n":3,"html":"Convolutional Neural Network(CNN)"},{"n":4,"html":"Gated Recurrent Unit(GRU)"}],"answer":[4]},{"id":"6a6a005a1bbde79cd2c72afe","number":57,"category":"빅데이터 모델링","type":"choice","subject":"<p>아래 그림처럼 의사결정나무를 활용해 변수의 값(X)에 따라 분류분석을 수행하려고 한다. 이 의사결정나무 구조에서 X₁과 X₂에 들어갈 값으로 알맞은 것은?</p><div class=\"q-fig\"><svg class=\"q-fig__svg\" viewBox=\"0 0 760 430\" width=\"760\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"X₁·X₂ 분기 의사결정나무(타원 노드)와 하단의 구간 A~E 수직선\"><defs><marker id=\"arw2\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"8\" markerHeight=\"8\" orient=\"auto\"><path d=\"M0 0L10 5L0 10z\" fill=\"currentColor\"/></marker></defs><ellipse cx=\"400\" cy=\"55\" rx=\"72\" ry=\"25\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"/><text x=\"400\" y=\"60\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\" font-style=\"italic\">X ≥ X₁</text><line x1=\"368\" y1=\"76\" x2=\"216\" y2=\"114\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"432\" y1=\"76\" x2=\"546\" y2=\"114\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"278\" y=\"90\" font-size=\"13\" fill=\"currentColor\" text-anchor=\"end\">YES</text><text x=\"502\" y=\"90\" font-size=\"13\" fill=\"currentColor\" text-anchor=\"start\">NO</text><ellipse cx=\"200\" cy=\"135\" rx=\"58\" ry=\"22\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"/><text x=\"200\" y=\"140\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\" font-style=\"italic\">X ≥ 8</text><ellipse cx=\"560\" cy=\"135\" rx=\"58\" ry=\"22\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"/><text x=\"560\" y=\"140\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\" font-style=\"italic\">X &lt; 5</text><line x1=\"178\" y1=\"153\" x2=\"126\" y2=\"195\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"222\" y1=\"153\" x2=\"274\" y2=\"195\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"140\" y=\"170\" font-size=\"13\" fill=\"currentColor\" text-anchor=\"end\">NO</text><text x=\"260\" y=\"170\" font-size=\"13\" fill=\"currentColor\" text-anchor=\"start\">YES</text><rect x=\"95\" y=\"195\" width=\"50\" height=\"34\" rx=\"8\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"/><text x=\"120\" y=\"218\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\">D</text><rect x=\"255\" y=\"195\" width=\"50\" height=\"34\" rx=\"8\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"/><text x=\"280\" y=\"218\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\">E</text><line x1=\"536\" y1=\"153\" x2=\"466\" y2=\"195\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"586\" y1=\"152\" x2=\"642\" y2=\"194\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"488\" y=\"170\" font-size=\"13\" fill=\"currentColor\" text-anchor=\"end\">NO</text><text x=\"628\" y=\"168\" font-size=\"13\" fill=\"currentColor\" text-anchor=\"start\">YES</text><rect x=\"435\" y=\"195\" width=\"50\" height=\"34\" rx=\"8\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"/><text x=\"460\" y=\"218\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\">C</text><ellipse cx=\"655\" cy=\"215\" rx=\"58\" ry=\"22\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"/><text x=\"655\" y=\"220\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\" font-style=\"italic\">X &lt; X₂</text><line x1=\"628\" y1=\"234\" x2=\"592\" y2=\"275\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"684\" y1=\"234\" x2=\"720\" y2=\"275\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"598\" y=\"254\" font-size=\"13\" fill=\"currentColor\" text-anchor=\"end\">NO</text><text x=\"712\" y=\"254\" font-size=\"13\" fill=\"currentColor\" text-anchor=\"start\">YES</text><rect x=\"560\" y=\"275\" width=\"50\" height=\"34\" rx=\"8\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"/><text x=\"585\" y=\"298\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\">B</text><rect x=\"698\" y=\"275\" width=\"50\" height=\"34\" rx=\"8\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"/><text x=\"723\" y=\"298\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\">A</text><line x1=\"50\" y1=\"370\" x2=\"712\" y2=\"370\" stroke=\"currentColor\" stroke-width=\"1.8\" marker-end=\"url(#arw2)\"/><line x1=\"170\" y1=\"362\" x2=\"170\" y2=\"378\" stroke=\"currentColor\" stroke-width=\"1.8\"/><line x1=\"320\" y1=\"362\" x2=\"320\" y2=\"378\" stroke=\"currentColor\" stroke-width=\"1.8\"/><line x1=\"440\" y1=\"362\" x2=\"440\" y2=\"378\" stroke=\"currentColor\" stroke-width=\"1.8\"/><line x1=\"590\" y1=\"362\" x2=\"590\" y2=\"378\" stroke=\"currentColor\" stroke-width=\"1.8\"/><text x=\"170\" y=\"352\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\">2</text><text x=\"320\" y=\"352\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\">5</text><text x=\"440\" y=\"352\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\">6</text><text x=\"590\" y=\"352\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\">8</text><text x=\"110\" y=\"402\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\">A</text><text x=\"245\" y=\"402\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\">B</text><text x=\"380\" y=\"402\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\">C</text><text x=\"515\" y=\"402\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\">D</text><text x=\"651\" y=\"402\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\">E</text></svg></div>","choices":[{"n":1,"html":"X₁=6, X₂=2"},{"n":2,"html":"X₁=6, X₂=5"},{"n":3,"html":"X₁=8, X₂=2"},{"n":4,"html":"X₁=8, X₂=5"}],"answer":[1]},{"id":"6a6a005a1bbde79cd2c72afd","number":58,"category":"빅데이터 모델링","type":"choice","subject":"<p>회귀분석 결과의 해석에 대한 설명 중 가장 옳지 않은 것은 무엇인가?</p>","choices":[{"n":1,"html":"반응 변수에 중요한 방식으로 영향을 줄 수 있는 상호 작용은 가능하다면 미리 식별해 두는 것이 바람직하다."},{"n":2,"html":"선형회귀식에서의 교호작용 해석 결과는 동일한 회귀계수로 생성한 다항회귀식에서도 같은 의미로 해석된다."},{"n":3,"html":"반응 변수와 하나 이상의 예측 변수 사이의 통계적 관계를 설명하는 공식을 도출할 수 있다."},{"n":4,"html":"교호작용(Interaction)이란 한 요인의 효과가 다른 요인의 수준에 의존하는 경우를 말하며, 교호작용도를 사용해 분석하고 교호작용도가 평행선으로 나타나면 교호작용이 없다고 해석한다."}],"answer":[2]},{"id":"6a6a005a1bbde79cd2c72af2","number":59,"category":"빅데이터 모델링","type":"choice","subject":"<p>데이터 분할(Data Splitting)과 관련하여 옳지 않은 설명은 무엇인가?</p>","choices":[{"n":1,"html":"모형 학습 과정에서 학습이 제대로 진행되고 있는지 점검하기 위해 검증용 데이터세트를 활용한다."},{"n":2,"html":"학습 데이터는 분석 모형을 만들기 위한 학습에 직접적으로 사용되는 데이터를 말한다."},{"n":3,"html":"학습 데이터와 검증 데이터세트에는 반드시 동일한 데이터 전처리 과정을 적용해야 한다."},{"n":4,"html":"성능 향상을 위해 하이퍼파라미터를 미세조정할 때는 검증 데이터보다 학습 데이터세트를 이용한다."}],"answer":[4]},{"id":"6a6a005a1bbde79cd2c72afb","number":60,"category":"빅데이터 모델링","type":"choice","subject":"<p>절편을 포함한 다중회귀분석 모형으로 회귀식을 추정하려고 하며, 독립변수는 12개이다. 종속변수 각각에 대해 세 가지 범주(계절, 월, 지역)를 고려해야 한다면 필요한 회귀계수는 모두 몇 개인가?</p>","choices":[{"n":1,"html":"24"},{"n":2,"html":"25"},{"n":3,"html":"36"},{"n":4,"html":"37"}],"answer":[4]},{"id":"6a6a005b1bbde79cd2c72b0c","number":61,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>인공신경망 모델을 학습시킬 때 과적합을 막기 위한 방법으로 옳지 않은 것은?</p>","choices":[{"n":1,"html":"가중치의 절댓값을 최대로 키운다."},{"n":2,"html":"입력 노드의 개수를 줄인다."},{"n":3,"html":"은닉층(Hidden Layer)의 개수를 줄인다."},{"n":4,"html":"Epoch 횟수를 감소시킨다."}],"answer":[1]},{"id":"6a6a005b1bbde79cd2c72b13","number":62,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>다음 중 시간 시각화 기법에 관한 설명으로 옳지 않은 것은?</p>","choices":[{"n":1,"html":"시간 시각화 기법은 시간의 흐름에 따라 데이터가 어떻게 변하는지를 나타내는 것으로, 일정 기간 동안 진행되는 변화와 트렌드를 추적할 때 주로 활용된다."},{"n":2,"html":"막대 그래프는 특정 시점이나 특정 구간에 해당하는 구간 값을 나타낸다."},{"n":3,"html":"점 그래프는 어떤 구간에서 끊임없이 변화하는 연속형 데이터 값을 나타내기 위해 사용된다."},{"n":4,"html":"계단 그래프는 점과 점을 곧바로 이어주는 방식이 아니라, 변화가 발생하기 전까지 일정한 선을 유지하다가 다음 값으로 넘어가는 지점에서 급격히 변하는 모습을 나타낸다."}],"answer":[3]},{"id":"6a6a005b1bbde79cd2c72b17","number":63,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>어떤 사건이나 주제를 마치 이야기를 풀어가듯 구성하고, 해당 사건(주제)이 전개되는 양상을 전방위로 연결해 시각적으로 보여주고자 할 때 활용되는 인포그래픽 기법은 무엇인가?</p>","choices":[{"n":1,"html":"만화형 인포그래픽"},{"n":2,"html":"스토리텔링형 인포그래픽"},{"n":3,"html":"나열형 인포그래픽"},{"n":4,"html":"타임라인 인포그래픽"}],"answer":[2]},{"id":"6a6a005b1bbde79cd2c72b10","number":64,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>하이퍼파라미터(Hyper Parameter, 초매개변수)의 최적화를 위해 활용하는 다음의 기법은 무엇인가?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>알려지지 않은 목적함수를 최대화(또는 최소화)할 수 있는 최적의 해를 탐색한다.</li><li>지금까지 확보한 데이터와 평가지표 사이의 숨겨진 관계를 Surrogate 모델을 이용해 모델링한다.</li><li>다음 탐색 지점의 결정에는 Acquisition Function을 활용한다.</li><li>Surrogate 모델은 일반적으로 가우시안 프로세스를 거쳐 생성되며, Acquisition Function을 통해 Expected Improvement가 최대화되는 방향으로 학습이 진행된다.</li></ul></div>","choices":[{"n":1,"html":"Bayesian Optimization"},{"n":2,"html":"Manual Search"},{"n":3,"html":"Grid Search"},{"n":4,"html":"NAdam(Adam with Nesterov Momentum)"}],"answer":[1]},{"id":"6a6a005b1bbde79cd2c72b12","number":65,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>데이터 시각화에 관한 설명 중 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"데이터 시각화는 인간의 시지각 능력에 기반하여 데이터의 이해와 설득을 돕기 위해 그림이나 도형과 같은 그래픽 요소들을 활용한다."},{"n":2,"html":"데이터 시각화를 하려면 시각화 툴(소프트웨어 설치)이 반드시 있어야 한다."},{"n":3,"html":"다양한 시각화 도구의 활용법과 장단점을 살펴본 뒤 데이터 특성에 적합한 방법과 도구를 선택한다."},{"n":4,"html":"데이터 시각화는 구조화, 시각화, 시각 표현이라는 단계를 거쳐 진행된다."}],"answer":[2]},{"id":"6a6a005b1bbde79cd2c72b18","number":66,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>머신러닝(기계학습)을 통계적 분석 기법과 비교한 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"통계적 분석은 공식에 따른 산출 결과를 얻는 반면, 기계학습은 데이터의 무작위 선정과 학습 과정 때문에 매번 다른 결과가 나오기도 한다."},{"n":2,"html":"통계적 분석은 표본을 뽑아 모집단을 추정하는 방식이 주가 되지만, 기계학습은 모집단 전체를 분석 대상으로 삼는다."},{"n":3,"html":"통계적 분석은 정형화된 수치형 데이터를 주로 활용해 결과를 얻지만, 기계학습은 비정형을 포함한 다양한 유형의 데이터를 함께 분석한다."},{"n":4,"html":"기계학습에서는 통계적 분석과 달리 결과물에 대한 수학적 공식을 도출하거나 해석할 수 없다."}],"answer":[4]},{"id":"6a6a005b1bbde79cd2c72b16","number":67,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>아래 보기에서 설명하는 특징에 해당하는 인포그래픽 기법은 무엇인가?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>역사적 사건이나 이벤트를 시간 순서에 따라 표현</li><li>전체 길이와 각 포인트별로 표시해야 할 부분을 고려해 아이콘, 일러스트레이션을 활용</li><li>사물이나 사람의 역사적 발전 과정을 시각적으로 나타냄</li><li>틈새시장에서 제품 또는 트렌드가 진화해 온 과정을 설명</li></ul></div>","choices":[{"n":1,"html":"프로세스 설명 인포그래픽"},{"n":2,"html":"타임라인 인포그래픽"},{"n":3,"html":"나열형 인포그래픽"},{"n":4,"html":"사용법 안내 인포그래픽"}],"answer":[2]},{"id":"6a6a005b1bbde79cd2c72b0d","number":68,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>인공신경망의 학습률(Learning Rate)에 관한 설명 중 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"경사하강법에서 학습률은 각 가중치에 대해 계산된 기울기 값을 어느 정도 반영할지를 결정하는 하이퍼파라미터를 말한다."},{"n":2,"html":"최적 학습률을 계산하는 표준화된 방법이 없으므로, 학습목적과 환경 등을 고려해 초기값을 정한 뒤 모형을 여러 차례 적용하면서 적절한 값을 찾아가는 과정을 거친다."},{"n":3,"html":"학습률은 모형 구축 전에 연구자가 정의하는 하이퍼파라미터이므로, 모형 수행 도중에는 변경하거나 조정하는 것이 불가능하다."},{"n":4,"html":"최솟값을 찾는 비용함수에서 학습률이 크면 데이터가 무질서하게 이탈하여 최저점에 수렴하지 못하며, 학습률이 작으면 학습시간이 오래 걸려 최저점에 도달하지 못한다."}],"answer":[3]},{"id":"6a6a005b1bbde79cd2c72b0e","number":69,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>매개변수와 초매개변수에 관한 설명 중 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"인공신경망 구축 시 매개변수와 초매개변수는 데이터 학습 전에 사용자가 정하는 값이다."},{"n":2,"html":"신경망의 가중치와 같이 학습과정을 통해 얻어지는 값을 매개변수라고 부른다."},{"n":3,"html":"학습률, 학습횟수, 배치 크기와 같이 사용자가 임의로 설정해야 하는 값을 초매개변수라고 부른다."},{"n":4,"html":"일반적으로 매개변수와 초매개변수는 모두 데이터 분석 모형의 구성을 조정해 가며 최적의 값을 찾는 과정을 거친다."}],"answer":[1]},{"id":"6a6a005b1bbde79cd2c72b15","number":70,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>인포그래픽(Infographics)에 관한 설명 중 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"인포그래픽은 스토리를 활용하여 정보를 전달하려는 경향이 두드러진다."},{"n":2,"html":"잘 만들어진 인포그래픽은 처음 접하는 사람도 직관적으로 정보를 쉽게 파악할 수 있다."},{"n":3,"html":"인포그래픽은 Information과 Graphics를 합친 용어로, 정보를 시각적 형태로 전달하는 것이다."},{"n":4,"html":"인포그래픽 시각화 작업을 수행하려면 소프트웨어를 설치하는 것이 필수적이다."}],"answer":[4]},{"id":"6a6a005b1bbde79cd2c72b0b","number":71,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>다음 중 적합도 검정에 Kolmogorov-Smirnov(K-S) Test 방법을 적용한 예제로 옳은 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>(가) K고등학교 3학년 학생들의 수학시험 점수가 정규분포를 따르는지를 검정한다.</li><li>(나) S은행에 도착하는 고객들의 도착 시간 간격이 감마분포를 따르는지를 검정한다.</li><li>(다) D공장에서 생산된 전자 부품의 수명이 지수분포를 따르는지를 검정한다.</li><li>(라) 글씨를 왼손으로 쓰는 사람과 오른손으로 쓰는 사람의 비율이 30% : 70%인지를 확인하고자 관측 도수와 기대 도수를 이용하여 검정한다.</li></ul></div>","choices":[{"n":1,"html":"(가), (나), (다)"},{"n":2,"html":"(가), (나), (다), (라)"},{"n":3,"html":"(가), (나)"},{"n":4,"html":"(가), (다), (라)"}],"answer":[1]},{"id":"6a6a005b1bbde79cd2c72b11","number":72,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>아래에 제시된 특징에 해당하는 군집분석 알고리즘은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>군집의 개수(클러스터 수)를 미리 지정할 필요가 없음(군집 수 파라미터 불필요)</li><li>특정 점을 중심으로 반경 Epsilon 안에 n개 이상의 점이 존재하면 하나의 군집으로 판단</li><li>밀도 기반의 클러스터링 기법으로, 점들이 조밀하게 모여 있을 때 밀도가 높은 영역을 군집화</li><li>클러스터 밀도에 따라 클러스터들을 서로 연결하므로 기하학적 형태의 군집도 만들 수 있음</li></ul></div>","choices":[{"n":1,"html":"K-means"},{"n":2,"html":"K-medoids"},{"n":3,"html":"DBSCAN"},{"n":4,"html":"Self Organizing Map"}],"answer":[3]},{"id":"6a6a005b1bbde79cd2c72b0f","number":73,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>초매개변수(Hyper Parameter)에 관한 설명 중 가장 적절한 것은?</p>","choices":[{"n":1,"html":"가중치(Weight)처럼 데이터 분석 모형이 스스로 설정하고 갱신하는 매개변수이다."},{"n":2,"html":"인공신경망 모형을 설계할 때 사람이 직접 지정해야 하는 매개변수에 해당하지 않는다."},{"n":3,"html":"최적화 기법을 활용해 적절한 값을 탐색(튜닝 등)하기도 하고, 분석가의 경험을 바탕으로 최적의 값을 결정하기도 한다."},{"n":4,"html":"데이터를 학습용과 검증용으로 나누어 분석모형을 구축하는 학습과정에서 얻어지는 값이다."}],"answer":[3]},{"id":"6a6a005b1bbde79cd2c72b09","number":74,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>다중 교차 검증(K-fold Cross Validation)에 관한 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"데이터의 수가 많지 않을 때 일반화된 모형을 구축할 수 있지만, 학습 시간이 오래 소요된다는 단점이 있다."},{"n":2,"html":"데이터 집합을 체계적으로 바꿔가며 모든 데이터에 대해 분석 모형의 성과를 측정하는 검증 방법이다."},{"n":3,"html":"K-1개의 훈련(학습) 데이터 집합과 1개의 검증(평가) 데이터 집합을 구성하여 분석 모형을 학습하고 평가한다."},{"n":4,"html":"K-1개의 검증(평가) 데이터 집합과 1개의 훈련(학습) 데이터 집합을 구성하여 분석 모형을 학습하고 평가한다."}],"answer":[4]},{"id":"6a6a005b1bbde79cd2c72b05","number":75,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>아래는 혼동행렬을 활용한 머신러닝 모델의 성능평가 결과를 나타낸 것이다. 다음 설명 중 옳지 않은 것을 고르시오.</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><table class=\"q-tbl\"><tr><th>실제 범주값 \\ 예측 범주값</th><th>Yes</th><th>No</th></tr><tr><td>Yes</td><td>True Positive(TP)</td><td>False Negative(FN)</td></tr><tr><td>No</td><td>False Positive(FP)</td><td>True Negative(TN)</td></tr></table></div>","choices":[{"n":1,"html":"특이도는 TN/(FP+TN)로 계산한다."},{"n":2,"html":"정밀도는 TP/(TP+FP)로 계산한다."},{"n":3,"html":"F1 스코어는 정밀도와 재현율의 기하평균을 통해 산출한다."},{"n":4,"html":"재현율은 TP/(TP+FN)로 계산한다."}],"answer":[3]},{"id":"6a6a005b1bbde79cd2c72b0a","number":76,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>아래 보기에서 설명하고 있는 교차 검증 기법으로 옳은 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>전체 n개의 관측값 가운데 단 하나의 관측값만 검증(시험) 데이터로 두고, 나머지 n-1개의 관측값을 훈련 데이터로 활용한다.</li><li>매 반복마다 데이터 포인트 하나를 골라 검증(시험) 데이터세트로 사용한다.</li><li>훈련에 n-1개의 관측값을 사용하기 때문에 Bias는 낮지만 과적합이 발생할 수 있으며, 랜덤성이 없다.</li><li>데이터세트가 클 경우 시간이 많이 소요되지만, 작은 데이터세트에서는 좋은 결과를 낸다.</li></ul></div>","choices":[{"n":1,"html":"Leave-one-out Cross Validation"},{"n":2,"html":"Holdout Cross Validation"},{"n":3,"html":"Shuffle-split Cross Validation"},{"n":4,"html":"K-fold Cross Validation"}],"answer":[1]},{"id":"6a6a005b1bbde79cd2c72b06","number":77,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>로지스틱 회귀분석을 수행한 결과 예측력을 갖춘 모형이라는 평가를 받았다. p = 민감도, c = 특이도 (0 &lt; c &lt; 1)일 때, 다음 중 옳지 않은 설명은?</p>","choices":[{"n":1,"html":"민감도가 커지면 특이도는 작아진다."},{"n":2,"html":"특이도가 커지면 민감도는 작아진다."},{"n":3,"html":"민감도와 특이도를 합하면 1보다 크다."},{"n":4,"html":"민감도에서 특이도를 뺀 값은 1(p-c=1)이다."}],"answer":[4]},{"id":"6a6a005b1bbde79cd2c72b14","number":78,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>다음 중 비교 시각화 기법에 관한 설명 가운데 옳지 않은 것은?</p>","choices":[{"n":1,"html":"체르노프 페이스는 데이터를 사람의 얼굴 이미지 형태로 나타내는 기법으로, 얼굴의 가로 너비, 세로 높이, 눈, 코, 입, 귀 등 각 부위에 변수를 대응시켜 데이터의 속성을 쉽게 파악할 수 있게 한다."},{"n":2,"html":"스타 차트는 각 변수의 표시 지점(중심점은 축이 나타내는 최솟값, 가장 먼 끝점은 최댓값)을 연결선으로 이어 별 모양의 도형으로 표현하며, 독립변수(설명변수)가 하나 늘어날 때마다 별의 개수도 늘어난다."},{"n":3,"html":"히트맵은 데이터 값을 색상으로 표현하는 기법으로, 하나의 대상에 해당하는 한 행을 왼쪽에서 오른쪽으로(또는 한 열을 위에서 아래로) 살펴보면 모든 변수를 확인할 수 있다."},{"n":4,"html":"평행 좌표계는 여러 개의 축을 평행하게 배치하여 만드는 기법으로, y축의 위쪽은 최댓값을, 아래쪽은 최솟값을 나타내며, 대상이 많은 데이터의 집단적 경향성을 파악하는 데 활용할 수 있다."}],"answer":[2]},{"id":"6a6a005b1bbde79cd2c72b08","number":79,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>다음은 K사 에어컨의 시험검사 결과로서 Gas 주입량(%)에 따른 냉방능력(Kcal/h)을 나타낸 것이다. 이에 관한 설명으로 옳은 것은?</p><div class=\"q-fig\"><svg class=\"q-fig__svg\" viewBox=\"0 0 760 390\" width=\"760\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"Gas 주입량이 A와 B 구간에서 증가한 뒤 C 구간에서 감소하는 냉방능력 산점도\"><defs><marker id=\"axisArrowNew\" viewBox=\"0 0 12 12\" refX=\"10\" refY=\"6\" markerWidth=\"8\" markerHeight=\"8\" orient=\"auto\"><path d=\"M1 1L11 6L1 11L4 6Z\" fill=\"currentColor\"/></marker></defs><text x=\"112\" y=\"25\" font-size=\"16\" fill=\"currentColor\">냉방능력(Kcal/h)</text><path d=\"M105 300V48\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" marker-end=\"url(#axisArrowNew)\"/><path d=\"M105 300H738\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" marker-end=\"url(#axisArrowNew)\"/><text x=\"735\" y=\"284\" font-size=\"16\" fill=\"currentColor\" text-anchor=\"end\">Gas주입량(%)</text><g fill=\"none\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\"0.35\"><path d=\"M105 250H680\"/><path d=\"M105 190H680\"/><path d=\"M105 130H680\"/><path d=\"M105 70H680\"/><path d=\"M300 70V300\" stroke-dasharray=\"5 7\"/><path d=\"M470 70V300\" stroke-dasharray=\"5 7\"/><path d=\"M680 70V300\" stroke-dasharray=\"5 7\"/></g><g fill=\"currentColor\" font-size=\"14\"><path d=\"M98 250H112\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"91\" y=\"255\" text-anchor=\"end\">2000</text><path d=\"M98 190H112\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"91\" y=\"195\" text-anchor=\"end\">4000</text><path d=\"M98 130H112\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"91\" y=\"135\" text-anchor=\"end\">6000</text><path d=\"M98 70H112\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"91\" y=\"75\" text-anchor=\"end\">8000</text></g><g stroke=\"currentColor\" stroke-width=\"1.6\"><path d=\"M300 293V307\"/><path d=\"M470 293V307\"/><path d=\"M680 293V307\"/></g><g fill=\"currentColor\" font-size=\"14\" text-anchor=\"middle\"><text x=\"300\" y=\"329\">90%</text><text x=\"470\" y=\"329\">100%</text><text x=\"680\" y=\"329\">120%</text></g><g fill=\"currentColor\" font-size=\"16\" font-weight=\"bold\" text-anchor=\"middle\"><text x=\"205\" y=\"360\">A</text><text x=\"385\" y=\"360\">B</text><text x=\"575\" y=\"360\">C</text></g><g fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\"><circle cx=\"145\" cy=\"252\" r=\"5.5\"/><circle cx=\"175\" cy=\"235\" r=\"5.5\"/><circle cx=\"205\" cy=\"242\" r=\"5.5\"/><circle cx=\"235\" cy=\"210\" r=\"5.5\"/><circle cx=\"265\" cy=\"218\" r=\"5.5\"/><circle cx=\"292\" cy=\"195\" r=\"5.5\"/><circle cx=\"315\" cy=\"182\" r=\"5.5\"/><circle cx=\"340\" cy=\"160\" r=\"5.5\"/><circle cx=\"365\" cy=\"170\" r=\"5.5\"/><circle cx=\"390\" cy=\"128\" r=\"5.5\"/><circle cx=\"420\" cy=\"112\" r=\"5.5\"/><circle cx=\"448\" cy=\"92\" r=\"5.5\"/><circle cx=\"485\" cy=\"108\" r=\"5.5\"/><circle cx=\"515\" cy=\"125\" r=\"5.5\"/><circle cx=\"545\" cy=\"137\" r=\"5.5\"/><circle cx=\"575\" cy=\"145\" r=\"5.5\"/><circle cx=\"605\" cy=\"163\" r=\"5.5\"/><circle cx=\"640\" cy=\"178\" r=\"5.5\"/><circle cx=\"668\" cy=\"190\" r=\"5.5\"/></g></svg></div>","choices":[{"n":1,"html":"A-B 구간에서는 음의 상관관계가, B-C 구간에서는 양의 상관관계가 나타난다."},{"n":2,"html":"A-B-C 전체 구간에서 상관계수 값은 양수이고, 선형의 상관관계를 보인다."},{"n":3,"html":"A-B, B-C 구간으로 구분하여 분석할 경우 유의한 상관관계가 존재한다."},{"n":4,"html":"A-B 구간의 기울기는 B-C 구간의 기울기에 비해 작다."}],"answer":[3]},{"id":"6a6a005b1bbde79cd2c72b07","number":80,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>종합병원, 의원 등 의료기관이 제공하는 서비스의 품질 수준을 점검하고자 할 때, Service Quality(SERVQUAL)에 기반한 평가지표에 해당하는 항목을 모두 고른 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>(가) 대응성</li><li>(나) 유형성</li><li>(다) 신뢰성</li><li>(라) 효율성</li><li>(마) 사용성</li><li>(바) 이식성</li></ul></div>","choices":[{"n":1,"html":"(가), (나), (다)"},{"n":2,"html":"(다), (라), (마), (바)"},{"n":3,"html":"(가), (다), (바)"},{"n":4,"html":"(나), (다), (마)"}],"answer":[1]}]};